// The flat per-method safe wrappers on `Tox` and `Options` are generated by
// apigen as mechanical delegations over the `core` tier; they are pulled in
// here as extra `impl` blocks. The struct definitions, constructors and
// bespoke methods below stay hand-written.
#[path = "../core/generated/safe_options.rs"]
mod safe_options;
#[path = "../core/generated/safe_tox.rs"]
mod safe_tox;

// The resource wrapper objects (`Friend`, `Group`, `File`, `Conference`) and
// the `Tox` resource accessors/constructors are generated by apigen as
// delegations over the `core` tier. Each generated wrapper module defines its
// struct, `Debug`/`From` impls and the delegating methods. `Friend` and `File`
// are fully generated, so they are pulled in directly. `tox/group.rs` and
// `tox/conference.rs` stay hand-written: they pull in the generated wrapper
// and add the few non-generatable methods (the `&Friend`-typed `invite_friend`
// / `invite`, the handler-based AV API and the `peer_list` helper) as an extra
// `impl` block.
#[path = "../core/generated/safe_friend.rs"]
mod friend;
#[path = "../core/generated/safe_file.rs"]
mod file;
mod group;
#[path = "../core/generated/safe_tox_resources.rs"]
mod safe_tox_resources;

pub struct Options {
    inner: core::Options,
}

impl Options {
    pub fn new() -> Result<Self> {
        let inner = core::Options::new().map_err(ToxError::OptionsNew)?;
        // Default experimental options that were in the original code
        let mut opts = Options { inner };
        opts.set_experimental_owned_data(true);
        Ok(opts)
    }

    // Most setters (`set_ipv6_enabled`, `set_start_port`, ...) are generated
    // in `safe_options.rs`. The two below stay hand-written: their `core`
    // counterparts return a `bool` that the safe API deliberately discards
    // for a vestigial `Result<()>`.
    pub fn set_proxy_host(&mut self, host: &str) -> Result<()> {
        self.inner.proxy_host(host);
        Ok(())
    }

    pub fn set_savedata_data(&mut self, data: &[u8]) -> Result<()> {
        self.inner.savedata_data(data);
        Ok(())
    }

    pub fn set_logger<L: ToxLogger + 'static>(&mut self, logger: L) {
        self.inner.set_logger(logger);
    }
}

pub(crate) struct Inner {
    pub(crate) core: core::Tox,
    #[allow(dead_code)] // Kept for ownership
    _options: Option<Options>,
}

pub struct Tox {
    pub(crate) inner: Inner,
}

// SAFETY: `Tox` owns a `*mut tox_sys::Tox`. The toxcore C library permits
// moving a `Tox` between threads, so `Send` is sound. `Tox` is deliberately
// NOT `Sync`: the safe API exposes `&self` methods that mutate the C object,
// so concurrent shared access (`&Tox` from two threads) would be a data
// race. Callers that need to share a `Tox` across threads must serialise
// access themselves (e.g. behind a mutex).
unsafe impl Send for Tox {}

impl Tox {
    pub fn new(options: Options) -> Result<Self> {
        let core = core::Tox::new(&options.inner).map_err(ToxError::New)?;
        Ok(Tox {
            inner: Inner {
                core,
                _options: Some(options),
            },
        })
    }

    pub fn iterate<H: ToxHandler>(&self, handler: &mut H) {
        core::tox_iterate(&self.inner.core, handler);
    }

    pub fn events(&self) -> Result<ToxEvents<'_>> {
        self.inner.core.events_init();
        let mut options = core::IterateOptions::new().map_err(ToxError::IterateOptionsNew)?;
        options.fail_hard(true);
        self.inner
            .core
            .events_iterate(Some(&options))
            .map_err(ToxError::EventsIterate)
    }

    // The flat per-method wrappers (`bootstrap`, `name`, `udp_port`, ...) are
    // generated in `safe_tox.rs`; the resource accessors (`friend`,
    // `friend_add`, ...) in `safe_tox_resources.rs`. `hash` stays here: it is
    // a static method, not a `&self` delegation.
    pub fn hash(data: &[u8]) -> Hash {
        core::Tox::hash(data)
    }

    // `tox_group_get_group_list_size` is attributed to the `group` subsystem
    // by the generator, so it is not among the generated flat `Tox` methods;
    // it is a Tox-level query, kept here by hand.
    pub fn group_count(&self) -> u32 {
        self.inner.core.group_get_group_list_size()
    }

    pub fn add_av_groupchat<'a, H: ToxAVConferenceHandler>(
        &'a self,
        handler: &H,
    ) -> Result<(Conference<'a>, ConferenceAvScope<'a, H>)> {
        let res = self.inner.core.add_av_groupchat(handler);
        if res >= 0 {
            let conf_num = ConferenceNumber(res as u32);
            Ok((
                self.conference(conf_num),
                ConferenceAvScope {
                    inner: &self.inner,
                    conference: conf_num,
                    _marker: std::marker::PhantomData,
                },
            ))
        } else {
            Err(ToxError::AvGroupError)
        }
    }

    pub fn join_av_groupchat<'a, H: ToxAVConferenceHandler>(
        &'a self,
        friend: &Friend,
        data: &[u8],
        handler: &H,
    ) -> Result<(Conference<'a>, ConferenceAvScope<'a, H>)> {
        let res = self
            .inner
            .core
            .join_av_groupchat(friend.get_number(), data, handler);
        if res >= 0 {
            let conf_num = ConferenceNumber(res as u32);
            Ok((
                self.conference(conf_num),
                ConferenceAvScope {
                    inner: &self.inner,
                    conference: conf_num,
                    _marker: std::marker::PhantomData,
                },
            ))
        } else {
            Err(ToxError::AvGroupError)
        }
    }
}

impl Drop for Tox {
    fn drop(&mut self) {
        // inner drops itself
    }
}

pub fn version() -> (u32, u32, u32) {
    (
        core::Tox::version_major(),
        core::Tox::version_minor(),
        core::Tox::version_patch(),
    )
}

pub fn is_compatible(major: u32, minor: u32, patch: u32) -> bool {
    core::Tox::version_is_compatible(major, minor, patch)
}
